import{_ as i,l as s,o as e,c as l,v as r,p as n,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"时钟域","description":"","frontmatter":{"title":"时钟域","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-domain.md","filePath":"cs/clock-domain.md","lastUpdated":1789023840000}'),h={name:"cs/clock-domain.md"};function E(_,a,m,A,u,F){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="时钟域" tabindex="-1">时钟域 <a class="header-anchor" href="#时钟域" aria-label="Permalink to &quot;时钟域&quot;">​</a></h1><div class="epigraph"><p>建立保持不等式默认同一时钟的两个边沿有确定关系；换一根无相位保证的时钟，采样窗口要对着亚稳来设计。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/flash-memory">闪存对照</a>引入了可能独立于 CPU 时钟的刷新与控制器。本课不重画 6T 单元，也不从分布式系统时钟另起。缺口是：<a href="/cs/setup-hold">建立保持</a>的 \\(T\\) 与 skew 只在<strong>同一时钟域</strong>成立。外设、DRAM、异步输入来自另一根时钟或无时钟，必须显式处理域交叉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单时钟同步：所有 FF 边沿同源，延迟可算。第二根时钟频率或相位无关，则源 FF 的 Q 相对目的时钟可以在任何时刻变，\\(t_{su}\\) 无法静态保证。缺口是时钟域交叉（CDC）：对单比特用两级同步器降低亚稳逃逸概率；对多比特用握手、FIFO（格雷码指针）避免采样撕裂。</p><p>本课只钉「域」与同步器直觉。不把 PLL 环路方程写完。</p><h3 id="两级同步器不是「等两拍就正确」" tabindex="-1">两级同步器不是「等两拍就正确」 <a class="header-anchor" href="#两级同步器不是「等两拍就正确」" aria-label="Permalink to &quot;两级同步器不是「等两拍就正确」&quot;">​</a></h3><p>亚稳逃逸概率指数下降，不是零。把同步器当成功能上的必对延时，会在极低失效率要求下误判。多比特若各自同步，会出现短暂非法编码：必须整体握手或格雷计数。</p><p><span class="marginnote">Harris 用亚稳窗口与同步器。DRAM 控制器相对 CPU 常是另一域或经 FIFO。本课不讲网络栏的 NTP；那是另一套时钟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>划分时钟域。跨域控制信号：双 FF 同步。跨域数据：先同步请求/应答，数据在握手稳定后视为静态。异步复位释放也要同步，避免释放靠近边沿。</p>',11)),(e(),n(p,null,{default:t(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLK1%5B%22%E6%97%B6%E9%92%9F%E5%9F%9F%20A%22%5D%20--%3E%20SYNC%5B%22%E5%90%8C%E6%AD%A5%E5%99%A8%20%2F%20FIFO%22%5D%0A%20%20CLK2%5B%22%E6%97%B6%E9%92%9F%E5%9F%9F%20B%22%5D%20--%3E%20SYNC%0A%20%20SYNC%20--%3E%20SAFE%5B%22%E5%9F%9F%20B%20%E5%86%85%E5%86%8D%E5%BD%93%E5%90%8C%E6%AD%A5%E9%80%BB%E8%BE%91%22%5D%0A%20%20SAFE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AD%98%E5%82%A8%E7%A8%8B%E5%BA%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>片上 SRAM 常与 CPU 同域。片外 DRAM 有自己的时序，CPU 侧用控制器在 CPU 时钟下呈现「若干拍后数据有效」。后课单周期教材忽略这一点；组成课主干承认真实主存是跨域/多拍的，教学模型可以再简化。</p><p>门控时钟是同一域内的派生时钟，必须当新的时序弧分析，不是 CDC，但会制造类似的偏斜。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全异步设计（握手流水线）当默认方法。不讨论量子或模拟锁相细节。多核一致性与时钟域正交，很后才出现。</p><p>后课默认：CPU 内核教学用单时钟；与内存、外设的边界要想到 CDC。下一课开始把「程序」放进存储器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>建立保持默认同域同源时钟。</li><li>跨域用同步器或 FIFO；多比特禁止各同步。</li><li>亚稳概率可压低，不能当零。</li><li>出处：Harris and Harris。</li></ul>',8))])}const D=i(h,[["render",E]]);export{f as __pageData,D as default};
